<script setup>
import {ref,watch,onBeforeUnmount} from 'vue'

import {bugAPI,evidenceWorkspace,evidenceLogHash} from '../../shared/bugEvidence.js'
import {toast} from '../../shared/composables/toast.js'
const props=defineProps({workItemID:Number})
const items=ref([]),loading=ref(false),error=ref(''),opening=ref(0)
let generation=0
async function load(){const token=++generation;loading.value=true;error.value='';try{const data=await bugAPI('research/work-items/'+props.workItemID+'/evidence');if(token===generation)items.value=data}catch(e){if(token===generation)error.value=e.message}finally{if(token===generation)loading.value=false}}
watch(()=>props.workItemID,()=>{items.value=[];load()},{immediate:true})
function report(v){evidenceWorkspace('api-center','#/test-execution?'+new URLSearchParams({service:v.service,environment:v.environment,run:String(v.run_id)}))}
function chooseRegression(){const v=items.value.find(v=>v.can_open&&v.service);evidenceWorkspace('api-center','#/test-cases?'+new URLSearchParams({bug:String(props.workItemID),...(v?{service:v.service,environment:v.environment}:{})}))}
async function regression(v){if(opening.value)return;opening.value=v.id;try{const data=await bugAPI('bug-evidence/'+v.id+'/regression');evidenceWorkspace('api-center',data.hash)}catch(e){toast(e.message,'warning')}finally{opening.value=0}}
onBeforeUnmount(()=>generation++)

import {ref as _viewRef} from 'vue'
const _view1=_viewRef([])


import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Badge,Button,Card,CardAction,CardContent,CardFooter,CardHeader,CardTitle,Empty,EmptyContent,EmptyDescription,EmptyHeader,Spinner} from '../../shared/shadcn-ui.js'
</script>
<template><Card :loading="loading" class="bug-evidence"><CardHeader><CardTitle>关联证据</CardTitle><CardAction><div class="flex flex-wrap items-center gap-2"><Button @click="chooseRegression" variant="ghost" size="default" type="button">选择回归用例</Button><Button @click="load" variant="ghost" size="default" type="button" :disabled="(loading)"><Spinner v-if="loading"/>刷新证据</Button></div></CardAction></CardHeader><CardContent class="min-w-0"><div v-if="error" role="alert">{{error}}<Button @click="load" variant="outline" size="default" type="button">重试</Button></div><ul v-else-if="items.length" class="divide-y"><li v-for="v in items" :key="v.id" class="py-3"><div class="evidence-item"><div class="evidence-heading"><div class="flex flex-wrap items-center gap-2"><Badge :variant="(v.kind==='test'?'blue':'purple')==='red'?'destructive':'secondary'">{{v.kind==='test'?'测试执行':'日志证据'}}</Badge><span v-if="v.can_open">{{v.service||'应用已移除'}} · {{v.environment}}</span><Badge v-if="v.status" :variant="(v.status==='success'?'green':v.status==='failed'?'red':'orange')==='red'?'destructive':'secondary'">{{({success:'通过',failed:'未通过',unknown:'待核对',canceled:'已停止'})[v.status]||v.status}}</Badge><span class="evidence-meta">{{v.owner}} · {{new Date(v.created_at*1000).toLocaleString()}}</span></div><div v-if="v.can_open" class="flex flex-wrap items-center gap-2"><Button v-if="v.kind==='test'" @click="report(v)" variant="ghost" size="default" type="button" :disabled="(!v.service)">原始报告 #{{v.run_id}}</Button><Button v-if="v.kind==='test'&&v.cases?.length" @click="regression(v)" variant="default" size="sm" type="button" :disabled="(!v.service||!!opening)||(opening===v.id)"><Spinner v-if="opening===v.id"/>发起回归</Button><Button v-if="v.log" @click="evidenceWorkspace('logs',evidenceLogHash(v))" variant="ghost" size="default" type="button">{{v.log.trace_id?'按 Trace ID 查询日志':'按时间范围查询日志'}}</Button></div></div><template v-if="v.can_open"><div v-if="v.cases?.length" class="evidence-meta">原执行用例：{{v.cases.map(c=>'TC-'+c.id+' v'+c.revision).join('、')}}<span v-if="v.failed_step"> · 失败步骤 {{v.failed_step}}</span><span v-if="v.failed_checks"> · {{v.failed_checks}} 项断言未通过</span></div><p v-if="v.note">{{v.note}}</p><Accordion v-if="v.snapshot||v.log" type="multiple" :model-value="(_view1||[]).map(String)" @update:model-value="_view1=$event"><AccordionItem :value="String(v.id)"><AccordionTrigger>留存摘要（已脱敏）</AccordionTrigger><AccordionContent force-mount v-show="!(!(_view1||[]).map(String).includes(String(v.id)))"><pre>{{v.log?.excerpt||v.snapshot}}</pre><span v-if="v.log" class="evidence-meta">用户选取的日志片段；查询结果以数据源当前权限和保留周期为准。</span></AccordionContent></AccordionItem></Accordion></template><p v-else class="evidence-meta">原记录和摘要仅关联人可见；关联不会授予日志或测试报告权限。</p></div></li></ul><Empty v-else><EmptyHeader><EmptyDescription>{{"可从测试报告或日志详情创建、关联 Bug，证据会保留在这里"}}</EmptyDescription></EmptyHeader></Empty></CardContent></Card></template>
<style scoped>.bug-evidence{margin-top:20px}.evidence-item{width:100%;min-width:0}.evidence-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.evidence-meta{color:var(--muted-foreground);font-size:.75rem;margin-top:8px}.evidence-item p{overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:220px;overflow:auto;font-family:var(--mono);font-size:.75rem;margin:0}</style>
